import {dashboard,mountDashboard} from './dashboard.js';
import {escapeHTML as e,imageURL,imageFile} from './store.js';
const defaults={title:'Seu universo começa aqui.',intro:'Dê espaço às suas ideias. O extraordinário está nos detalhes.',bannerTitle:'Imagine sem limites.\nCrie com propósito.',bannerText:'Dos primeiros esboços aos reinos mais distantes.\nCada ideia tem um lugar no seu universo.',cover:'assets/castle.jpg',quote:'Não são todos os que vagueiam que estão perdidos.',author:'J. R. R. Tolkien',hero:true,stats:true,recent:true,map:true,inspiration:true,shortcuts:true};
export const overviewSettings=w=>({...defaults,...w.overview,cover:imageURL(w.overview?.cover)||defaults.cover});
export function renderOverview(w,counts,heading,btn,state){const o=overviewSettings(w);const settings=`<details id="overviewSections" class="overview-controls"><summary>☷ Personalizar início</summary><div>${[['hero','Capa'],['stats','Contadores'],['recent','Recentes'],['map','Mapa'],['inspiration','Inspirações'],['shortcuts','Atalhos']].map(([key,label])=>`<label>${label}<input type="checkbox" data-overview-section="${key}" ${o[key]?'checked':''}></label>`).join('')}</div></details>`;return dashboard(w,o,counts,btn,settings,state);}

export function customizeOverview(w,modal,field,onSave){const o=overviewSettings(w);modal('Seu jeito de imaginar',field('Título da visão geral','title',o.title)+field('Introdução','intro',o.intro)+field('Título da capa','bannerTitle',o.bannerTitle,'textarea')+field('Descrição da capa','bannerText',o.bannerText,'textarea')+'<label class="field"><span>Imagem de capa (opcional)</span><input name="cover" type="file" accept="image/*"></label><label class="help"><input type="checkbox" name="resetCover" style="width:auto"> Restaurar a imagem de capa original</label>'+field('Citação','quote',o.quote,'textarea')+field('Autor da citação','author',o.author)+'<h3 style="margin:22px 0 10px">O que você quer ver?</h3>'+[['hero','Capa do universo'],['stats','Contadores'],['recent','Documentos recentes'],['map','Mapa em destaque'],['inspiration','Citação'],['shortcuts','Atalhos criativos']].map(([key,label])=>`<label class="overview-toggle"><span>${label}</span><input type="checkbox" name="${key}" ${o[key]?'checked':''}></label>`).join(''),async data=>{const next={...w.overview};for(const key of ['title','intro','bannerTitle','bannerText','quote','author'])next[key]=String(data.get(key)||'').trim().slice(0,1000);for(const key of ['hero','stats','recent','map','inspiration','shortcuts'])next[key]=data.has(key);next.cover=data.has('resetCover')?defaults.cover:o.cover;if(data.get('cover')?.size)next.cover=await imageFile(data.get('cover'));w.overview=next;onSave();});}

export function mountOverview(main,w,{save,notify,rerender,sectionsOpen=false,openDocument,navigate}){const abort=new AbortController(),opts={signal:abort.signal};if(sectionsOpen)main.querySelector('#overviewSections').open=true;const settings=overviewSettings(w);w.overview={...settings};const fields=[['.page-heading h1','title'],['.page-heading p','intro'],['.hero-content h2','bannerTitle'],['.hero-content p','bannerText'],['[data-overview-field=quote]','quote'],['[data-overview-field=author]','author']];for(const [selector,key] of fields){const el=main.querySelector(selector);if(!el)continue;el.contentEditable='plaintext-only';el.classList.add('inline-personalizable');el.setAttribute('aria-label','Editar '+({title:'título da visão geral',intro:'introdução',bannerTitle:'título da capa',bannerText:'descrição da capa',quote:'citação',author:'autor'}[key]));el.title='Clique para editar';el.addEventListener('input',()=>{w.overview[key]=el.innerText.slice(0,1000);save();},opts);el.addEventListener('keydown',event=>{if(event.key==='Escape'){el.blur();}if(event.key==='Enter'&&['title','intro','author'].includes(key)){event.preventDefault();el.blur();}},opts);}
main.querySelectorAll('[data-overview-section]').forEach(input=>input.onchange=()=>{w.overview[input.dataset.overviewSection]=input.checked;save();rerender(true);});const file=main.querySelector('#overviewCoverFile');main.querySelector('#changeCover')?.addEventListener('click',()=>file.click(),opts);if(file)file.onchange=async()=>{try{if(!file.files[0])return;w.overview.cover=await imageFile(file.files[0]);save();rerender();notify('Capa atualizada.');}catch(error){notify(error.message);}};main.querySelector('#resetCover')?.addEventListener('click',()=>{w.overview.cover=defaults.cover;save();rerender();},opts);const stopDashboard=mountDashboard(main,w,{save,rerender,openDocument,navigate});return()=>{abort.abort();stopDashboard();};}
